  "BEGLEITER-EI!": "NUOVO UOVO!",
  "{egg}! Bring es ins Brutnest im Versteck.": "{egg}! Portalo al Nido nel Rifugio.",
  "Ein Begleiter-Ei! Dein Brutnest ist voll – dafür +1 Glücksmünze.": "Un uovo di compagno! Il tuo nido è pieno – in cambio +1 Moneta della Fortuna.",
  "SCHILD": "SCUDO",
  "LEBENSBUND +{n}": "SIMBIOSI +{n}",
  "Nestmutter Gunda": "Chioccia Gunda",
  "Wärme, Futter, Zuwendung. Fehlt eins davon, schläft das Küken im Ei einfach weiter.": "Calore, cibo, affetto. Se ne manca uno, il pulcino nell'uovo continua semplicemente a dormire.",
  "Sind alle drei Bedürfnisse gut gefüllt, wächst ein Ei anderthalbmal so schnell.": "Se tutti e tre i bisogni sono ben soddisfatti, un uovo cresce una volta e mezza più in fretta.",
  "Streichle die Eier ruhig. Die spüren das. Wirklich.": "Accarezza pure le uova. Lo sentono. Davvero.",
  "Aus einem schmutzigen Ei schlüpft meist eine Schnecke. Aber man liebt sie trotzdem.": "Da un uovo sporco di solito nasce una lumaca. Ma le si vuole bene lo stesso.",
  "Ein mythisches Ei braucht Tage. Und Sternenstaub. Und Geduld. Vor allem Geduld.": "Un uovo mitico richiede giorni. E polvere di stelle. E pazienza. Soprattutto pazienza.",
  "Brutnest: Ein Ei ist bereit zum Schlüpfen!": "Nido: un uovo è pronto a schiudersi!",
  "Brutnest: {n} Eier sind bereit zum Schlüpfen!": "Nido: {n} uova sono pronte a schiudersi!",
  "Brutnest: Ein Ei braucht dich – es wächst gerade nicht.": "Nido: un uovo ha bisogno di te – al momento non cresce.",
  "Brutnest: {n} Eier brauchen dich – sie wachsen gerade nicht.": "Nido: {n} uova hanno bisogno di te – al momento non crescono.",
  "BEREIT": "PRONTO",
  "Ein Ei! Das hast du dem Boss abgenommen? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "Un uovo! L'hai preso al boss? Portalo da me al Nido – ora abito nel Rifugio.",
  "Ein Ei! Wo hast du das denn gefunden? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "Un uovo! E dove l'hai trovato? Portalo da me al Nido – ora abito nel Rifugio.",
  "Halt es warm, füttere es und schenk ihm Zuwendung. Dann wächst es – auch während du unterwegs bist.": "Tienilo al caldo, nutrilo e dagli affetto. Così cresce – anche mentre sei in giro.",
  "Irgendwann schlüpft daraus dein erster Begleiter. Komm, ich zeig dir das Nest.": "Prima o poi ne nascerà il tuo primo compagno. Vieni, ti mostro il nido.",
  "Ich bin Gunda und kümmere mich ab jetzt um das Brutnest im Versteck.": "Sono Gunda e d'ora in poi mi occupo del Nido nel Rifugio.",
  "Eier schlüpfen nicht mehr von allein: Halt sie warm, füttere sie und schenk ihnen Zuwendung. Dann wachsen sie, auch während du unterwegs bist.": "Le uova non si schiudono più da sole: tienile al caldo, nutrile e dagli affetto. Così crescono, anche mentre sei in giro.",
  "DEIN ERSTES EI": "IL TUO PRIMO UOVO",
  "NEU: DAS BRUTNEST": "NOVITÀ: IL NIDO",
