  "Fällst du in den Verlorenen Landen, rettet dein Begleiter, was in seinem Beutel liegt. Seltenere Arten tragen mehr, das Talent „Große Taschen“ gibt weitere Plätze.": "Se cadi nelle Terre Perdute, il tuo compagno salva ciò che ha nella sua borsa. Le specie più rare portano di più, il talento «Tasche capienti» dà altri posti.",
