  "In diesem Code steckt ein Begleiter – diese Version kann ihn noch nicht annehmen. Der Code bleibt gültig.": "Questo codice contiene un compagno – questa versione non può ancora accettarlo. Il codice resta valido.",
  "Kein Platz für einen weiteren Begleiter. Der Code bleibt gültig.": "Non c'è posto per un altro compagno. Il codice resta valido.",
  "Der Begleiter konnte nicht übernommen werden. Der Code bleibt gültig.": "Impossibile accogliere il compagno. Il codice resta valido.",
  "Das hat nicht geklappt.": "Non ha funzionato.",
  "Tauschcode erkannt – du findest ihn im Hauptmenü unter „Tausch empfangen“.": "Codice di scambio rilevato – lo trovi nel menu principale in «Ricevi scambio».",
