  "Behalten": "Tieni",
  "Wählen": "Scegli",
  "Daraus wird ein Tauschcode, den du als Link teilst. Wer ihn zuerst einlöst, bekommt es.": "Diventa un codice di scambio da condividere come link. Chi lo riscatta per primo lo riceve.",
