  "Tippe einen Gegenstand aus deinem Beutel an. Angelegte Ausrüstung bleibt bei dir.": "Tocca un oggetto della tua borsa. L'equipaggiamento indossato resta a te.",
  "Du hast noch keine Materialien, Edelsteine oder Bauteile.": "Non hai ancora materiali, gemme o componenti.",
  "Schieb die Regler: So viel kommt ins Bündel.": "Sposta i cursori: ecco quanto finisce nel pacco.",
