  "Du hast noch keinen Begleiter.": "Non hai ancora un compagno.",
  "EIER": "UOVA",
  "Beim Verschenken beginnt das Ausbrüten von vorn.": "Se lo regali, la cova ricomincia da capo.",
  "Noch nichts ausgewählt.": "Ancora niente di selezionato.",
  "„{name}“ verlässt deinen Beutel. Daraus wird ein Tauschcode, den genau eine Person einlösen kann.": "«{name}» lascia la tua borsa. Diventa un codice di scambio che una sola persona può riscattare.",
  "Diese Dinge verlassen deinen Vorrat. Daraus wird ein Tauschcode, den genau eine Person einlösen kann.": "Queste cose lasciano le tue scorte. Diventano un codice di scambio che una sola persona può riscattare.",
  "{name} verlässt dich und wartet im Tauschcode auf ein neues Zuhause.": "{name} ti lascia e aspetta una nuova casa nel codice di scambio.",
  "Das Ei verlässt dein Nest. Beim neuen Besitzer beginnt das Ausbrüten von vorn.": "L'uovo lascia il tuo nido. Dal nuovo proprietario la cova ricomincia da capo.",
  "WIRKLICH VERSCHENKEN?": "REGALARE DAVVERO?",
  "Ja, Tauschcode erstellen": "Sì, crea il codice di scambio",
