  "Fertig": "Fatto",
  "Schick den Link an deinen Freund – zum Beispiel per WhatsApp. Er öffnet ihn und nimmt das Geschenk an. Den Code findest du später auch im Verlauf.": "Manda il link al tuo amico – per esempio su WhatsApp. Lo apre e accetta il regalo. Il codice lo ritrovi anche nello Storico.",
