  "Dein neuer Begleiter wartet bei deinen Begleitern.": "Il tuo nuovo compagno ti aspetta insieme agli altri compagni.",
  "Das Ei liegt in deinem Nest und schlüpft nach genug Kämpfen.": "L'uovo è nel tuo nido e si schiuderà dopo abbastanza battaglie.",
