  "Man sagt, {name} habe einst {deed}.": "Si dice che {name} un tempo abbia {deed}.",
  "Seit {n} Wintern haust {name} in {place}.": "Da {n} inverni {name} dimora a {place}.",
  "{name} sammelt {thing} – und die Knochen derer, die danach fragen.": "{name} colleziona {thing} – e le ossa di chi fa domande.",
