  "Siegel der Welt": "Sigillo del Mondo",
  "Giftluft": "Aria tossica",
  "Giftluft! Ohne Kräutermaske brennt jeder Atemzug.": "Aria tossica! Senza la Maschera d'erbe ogni respiro brucia.",
  "Eisige Kälte": "Freddo glaciale",
  "Eisige Kälte! Ohne Feuermantel wirst du langsam und frierst.": "Freddo glaciale! Senza il Mantello di fuoco rallenti e ti congeli.",
  "Glühende Hitze": "Calore rovente",
  "Glühende Hitze! Ohne Feuermantel versengt sie dich.": "Calore rovente! Senza il Mantello di fuoco ti ustiona.",
  "Finsternis! Ohne Schattenlaterne siehst du kaum die Hand vor Augen.": "Oscurità! Senza la Lanterna delle ombre non vedi a un palmo dal naso.",
  "Sturm": "Tempesta",
  "Sturm! Ohne Sturmfeder werfen dich die Böen umher.": "Tempesta! Senza la Piuma della tempesta le raffiche ti sballottano.",
  "Sog der Leere": "Risucchio del Vuoto",
  "Die Leere saugt an deiner Kraft! Ohne Leere-Anker schwindet sie.": "Il Vuoto ti risucchia le forze! Senza l'Ancora del Vuoto svaniscono.",
  "Blutdunst": "Miasma di sangue",
  "Blutdunst! Ohne Kräutermaske II saugt er dir das Leben aus.": "Miasma di sangue! Senza la Maschera d'erbe II ti succhia la vita.",
  "Sporenluft": "Aria di spore",
  "Sporenluft! Ohne Kräutermaske II vergiftet sie dich.": "Aria di spore! Senza la Maschera d'erbe II ti avvelena.",
  "Höhensturm": "Bufera d'altura",
  "Höhensturm! Ohne Eishaken II reißt er dich von den Füßen.": "Bufera d'altura! Senza la Piccozza II ti fa perdere l'equilibrio.",
  "Seelensog": "Risucchio d'anime",
  "Seelensog! Ohne Brückenstein II zehren die Seelen an Kraft und Leben.": "Risucchio d'anime! Senza la Pietra del ponte II le anime ti prosciugano forze e vita.",
  "Sternenglut! Ohne Feuermantel II verbrennst du.": "Brace stellare! Senza il Mantello di fuoco II bruci.",
  "Grabeskälte": "Gelo sepolcrale",
  "Grabeskälte! Ohne Feuermantel II erstarrst du.": "Gelo sepolcrale! Senza il Mantello di fuoco II ti congeli.",
  "Traumnebel": "Nebbia dei sogni",
  "Traumnebel! Ohne Schattenlaterne II wirst du müde und siehst kaum etwas.": "Nebbia dei sogni! Senza la Lanterna delle ombre II ti assonni e non vedi quasi nulla.",
  "Zeitsog": "Risucchio del tempo",
  "Zeitsog! Ohne Gezeitenperle II zerrt die Zeit an dir.": "Risucchio del tempo! Senza la Perla delle maree II il tempo ti strattona.",
  "Splitterregen": "Pioggia di schegge",
  "Splitterregen! Ohne Dornenklinge II schneiden dich die Splitter.": "Pioggia di schegge! Senza la Lama delle spine II le schegge ti tagliano.",
