  "Bald bricht die Nacht herein – dann streifen mehr und stärkere Gegner umher.": "Presto calerà la notte – e in giro ci saranno più nemici, e più forti.",
  "NACHT": "NOTTE",
  "DIE NACHT BRICHT AN": "CALA LA NOTTE",
  "Jäger der Nacht sind unterwegs. Halte ein Tor oder Leuchtfeuer im Blick!": "I Cacciatori della Notte sono in giro. Tieni d'occhio un portale o un faro!",
  "MORGEN": "ALBA",
