  "Vögel fliegen nur in den Endlosen Landen.": "Gli uccelli volano solo nelle Terre Infinite.",
  "Keine Vögel dabei. Die Voliere im Versteck züchtet sie, Händler Bodo verkauft manchmal einen.": "Nessun uccello con te. La Voliera nel Rifugio li alleva, il Mercante Bodo a volte ne vende uno.",
