  "Wer versteigert, braucht Geduld. Wer bietet, braucht Nerven.": "Chi mette all'asta ha bisogno di pazienza. Chi offre, di nervi saldi.",
  "Ein Legendärer unter Marktwert? Kommt vor. Selten. Aber es kommt vor.": "Un Leggendario sotto il valore di mercato? Capita. Di rado. Ma capita.",
