  "Die Uhr deines Geräts wurde zurückgestellt. Der Basar wartet, bis sie wieder stimmt (noch {t}).": "L'orologio del tuo dispositivo è stato spostato indietro. Il Bazar aspetta che torni giusto (ancora {t}).",
