  "Stufe {lv} · Geh zu einer Station und interagiere": "Livello {lv} · Raggiungi una stazione e interagisci",
  "Willkommen im Versteck, {name}. Noch ist es eine Ruine.": "Ti do il benvenuto nel Rifugio, {name}. Per ora è solo una rovina.",
  "Die Gerüste dort? Dort bauen wir Schmiede, Labor, Schatzkammer und mehr. Geh hin und sieh, was es kostet.": "Le impalcature laggiù? Lì costruiremo la Forgia, il Laboratorio, la Sala del tesoro e altro ancora. Vai a vedere quanto costano.",
  "Holz und Stein holst du dir am Rand des Verstecks: Hau auf die Bäume und Felsen ein. Und jeder Ausbau braucht seine Zeit – meine Leute sind fleißig, aber zaubern können sie nicht.": "Legno e pietra li trovi ai margini del Rifugio: prendi a colpi alberi e rocce. E ogni miglioramento richiede il suo tempo – i miei ragazzi sono instancabili, ma non sanno fare magie.",
  "Am Lagerfeuer kannst du einmal pro Akt rasten. Und das Portal bringt dich zurück zur Weltkarte.": "Al falò puoi riposare una volta per Atto. E il portale ti riporta alla Mappa del mondo.",
