  "Einmal pro Akt kannst du hier vollständig heilen.": "Una volta per Atto puoi curarti completamente qui.",
  "Rasten (voll heilen)": "Riposa (cura completa)",
  "Am Feuer erzählen": "Racconti al fuoco",
  "AUSBAU-ÜBERSICHT · VERSTECK-STUFE {lv}": "PANORAMICA MIGLIORAMENTI · LIVELLO RIFUGIO {lv}",
  "Tränke: {n} · heilen {p}": "Pozioni: {n} · curano {p}",
  "Brauen": "Prepara",
  "ELIXIERE": "ELISIR",
  "Trinken": "Bevi",
  "Elixiere gibt es ab Stufe 3.": "Gli elisir sono disponibili dal livello 3.",
  "Antippen zum Auswählen, nochmal antippen zum Verschieben. Das Lager teilen sich alle deine Helden.": "Tocca per selezionare, tocca di nuovo per spostare. Il deposito è condiviso da tutti i tuoi eroi.",
  "Sortieren": "Ordina",
  "Ins Lager legen": "Metti nel deposito",
  "In den Beutel": "Metti nella borsa",
  "Tippe einen Gegenstand an.": "Tocca un oggetto.",
  "Dauerhafter Bonus für alle Helden: {bonus}. Schlag die Trainingspuppe, um deinen Schaden pro Sekunde zu sehen.": "Bonus permanente per tutti gli eroi: {bonus}. Colpisci il manichino per vedere i tuoi danni al secondo.",
  "+{n} % Schaden und LP": "+{n}% danni e PS",
  "Die Kumpel fördern für jeden geschafften Raum (bis zu 25).": "I minatori estraggono per ogni stanza completata (fino a 25).",
  "Der Garten wächst für jeden geschafften Raum (bis zu 25).": "L'orto cresce per ogni stanza completata (fino a 25).",
  "Seit dem letzten Besuch: {n}.": "Dall'ultima visita: {n}.",
  "1 Raum": "1 stanza",
  "{n} Räume": "{n} stanze",
  "Einsammeln": "Raccogli",
  "Noch nichts zum Einsammeln. Schaff ein paar Räume!": "Ancora niente da raccogliere. Completa qualche stanza!",
  "Eingesammelt!": "Raccolto!",
  "CHRONIK {n}/{max}": "CRONACA {n}/{max}",
  "GESCHICHTE": "STORIA",
  "BESTIARIUM": "BESTIARIO",
  "Chronikseiten findest du in Truhen, bei Elite-Gegnern, Bossen und in Gräbern. Ab Bibliothek-Stufe 3 häufiger.": "Le pagine di cronaca si trovano nei forzieri, presso i nemici Élite, i boss e nelle tombe. Dal livello 3 della Biblioteca più spesso.",
  "Prolog": "Prologo",
  "Akt {act}: {title}": "Atto {act}: {title}",
  "Die Qual": "Il Tormento",
  "1 GLÜCKSMÜNZE": "1 MONETA DELLA FORTUNA",
  "{n} GLÜCKSMÜNZEN": "{n} MONETE DELLA FORTUNA",
  "REINER ZUFALL": "PURA FORTUNA",
  "GLÜCKSROLLE": "RULLO DELLA FORTUNA",
  "Gratis-Dreh der Glückswoche!": "Giro gratis del giorno!",
  "Gratis drehen!": "Giro gratis!",
  "Glücksrolle drehen (1 {coin})": "Gira il rullo (1 {coin})",
  "1 {coin} kaufen ({gold} Gold)": "Compra 1 {coin} ({gold} oro)",
  "SCHICKSALSTRUHEN": "FORZIERI DEL DESTINO",
  "Glücksmünzen gibt es von Bossen, Champions, seltenen Truhen, der Tages-Challenge und Schreinen Fortunas. Jede Drehung ist reiner Zufall mit den gezeigten Chancen – Mythisch kann beim ersten Dreh kommen oder erst nach sehr vielen.": "Le Monete della Fortuna si ottengono da boss, campioni, forzieri rari, dalla Sfida giornaliera e dai Santuari di Fortuna. Ogni giro è pura fortuna con le probabilità indicate – il Mitico può uscire al primo giro o dopo moltissimi.",
  "Alle Kosmetik gesammelt – 4 Glücksmünzen zurück": "Tutti i cosmetici raccolti – 4 Monete della Fortuna restituite",
  "Kosmetik: {name} (im Spiegel anlegen)": "Cosmetico: {name} (indossalo allo Specchio)",
  "+2 Glücksmünzen": "+2 Monete della Fortuna",
  "MYTHISCH: {name}": "MITICO: {name}",
  "Begleiter-Ei: {egg}!": "Uovo di compagno: {egg}!",
  "Ein Begleiter-Ei!": "Un uovo di compagno!",
  "{name} Stufe {lv}": "{name} livello {lv}",
  "Fertig gebaut: {list}!": "Costruzione completata: {list}!",
  "Während du weg warst, fertig gebaut: {list}": "Mentre eri via, costruzione completata: {list}",
  "{n} s": "{n} s",
  "{m} Min. {s} s": "{m} min {s} s",
  "{m} Min.": "{m} min",
  "{h} Std.": "{h} h",
  "Beide Baumeister bauen gerade.": "Entrambi i costruttori sono all'opera.",
  "Der Baumeister baut gerade: {name} (noch {t})": "Il costruttore sta lavorando a: {name} (ancora {t})",
  "Fertigstellen": "Completa",
  "Sofort fertig": "Completa ora",
  "Beide Baumeister haben gerade nichts zu tun.": "Entrambi i costruttori al momento non hanno niente da fare.",
  "Der Baumeister hat gerade nichts zu tun. Ab Versteck-Stufe 50 hilft ein zweiter mit.": "Il costruttore al momento non ha niente da fare. Dal livello 50 del Rifugio ne arriva un secondo ad aiutarlo.",
  "Im Bau: {name}": "In costruzione: {name}",
  "Ein Baumeister ist noch frei.": "Un costruttore è ancora libero.",
  "kostenlos": "gratis",
  "SOFORT FERTIG?": "COMPLETARE ORA?",
  "{name} wird sofort fertig und spart {t} Bauzeit.": "Completa subito {name} e risparmia {t} di costruzione.",
  "Preis: {p}": "Prezzo: {p}",
  "Ja, bezahlen": "Sì, paga",
  "Nicht genug Glücksmünzen": "Monete della Fortuna insufficienti",
  "Fenrik näht größere Taschen – sie gelten für alle deine Helden.": "Fenrik cuce sacche più grandi – valgono per tutti i tuoi eroi.",
  "Beutel des Helden": "Borsa dell'eroe",
  "Ausrüstung, die du mit dir trägst. Materialien, Edelsteine und Gold brauchen keinen Platz.": "L'equipaggiamento che porti con te. Materiali, gemme e oro non occupano posti.",
  "Rucksack in den Landen": "Zaino nelle Terre",
  "Was du in den Endlosen Landen findest – bis du heimkehrst.": "Ciò che trovi nelle Terre Infinite – finché non torni a casa.",
  "Begleiter-Tasche": "Sacca del compagno",
  "Zusätzliche Plätze in der Tasche deines Begleiters.": "Posti extra nella sacca del tuo compagno.",
  "Ein guter Beutel ist wie ein guter Freund: Er trägt, ohne zu klagen.": "Una buona borsa è come un buon amico: porta il peso senza lamentarsi.",
  "Bring mir Leder und Pflanzenfaser, dann nähe ich dir Taschen, in die ein halber Drachenhort passt.": "Portami cuoio e fibra vegetale, e ti cucirò sacche in cui entra mezzo tesoro di un drago.",
  "Gold und Edelsteine zählst du nur – aber Klingen und Rüstungen, die brauchen Platz.": "Oro e gemme li conti e basta – ma lame e armature, quelle sì che occupano spazio.",
  "Die Rucksäcke für die Lande nähe ich doppelt. Was dort reißt, ist für immer verloren.": "Gli zaini per le Terre li cucio a doppio filo. Quello che si strappa laggiù è perso per sempre.",
  "Ein Vogel kennt immer den Weg nach Hause. Das ist mehr, als man von den meisten Helden sagen kann.": "Un uccello conosce sempre la via di casa. È più di quanto si possa dire della maggior parte degli eroi.",
  "Federn, Holz und ein wenig Faser – mehr braucht ein Nest nicht. Und Geduld.": "Piume, legno e un po' di fibra – a un nido non serve altro. E pazienza.",
  "Raben sind klug. Zu klug. Zähl nach, was sie heimbringen.": "I corvi sono furbi. Troppo furbi. Ricontrolla ciò che portano a casa.",
  "Eine Phönixfeder verbrennt nie. Man sagt, sie fliegt sogar durch die Leere.": "Una piuma di fenice non brucia mai. Si dice che voli persino attraverso il Vuoto.",
  "Neu: Am Rand des Verstecks wachsen Bäume, Felsen und Büsche – hau drauf für Holz, Stein und Fasern. Jeder Ausbau braucht jetzt Bauzeit.": "Novità: ai margini del Rifugio crescono alberi, rocce e cespugli – colpiscili per ottenere legno, pietra e fibre. Ogni miglioramento ora richiede tempo di costruzione.",
  "Tipp: Bäume, Felsen und Büsche kannst du mit Angriffen abbauen. Holz, Stein und Fasern brauchst du zum Bauen im Versteck.": "Consiglio: puoi abbattere alberi, rocce e cespugli con i tuoi attacchi. Legno, pietra e fibre ti servono per costruire nel Rifugio.",
  "ACKER · {n} BEETE": "CAMPO · {n} PARCELLE",
  "Säe Samen und ernte in Echtzeit – das Feld wächst auch, während du unterwegs bist. Samen gibt es von Büschen, Kräutern und aus dem Garten.": "Semina e raccogli in tempo reale – il campo cresce anche mentre sei in giro. I semi si ottengono da cespugli, erbe e dall'Orto.",
  "Leeres Beet": "Parcella vuota",
  "Unten bei SAATGUT etwas säen": "Semina qualcosa qui sotto, in SEMENTI",
  "Reif! {out}": "Raccolto pronto! {out}",
