  "SIEHE AUCH": "VEDI ANCHE",
  "KLINGENHORT": "KLINGENHORT",
  "Willkommen im Handbuch": "Benvenuto nel Manuale",
  "Hier steht alles über Klingenhort: jede Funktion, jeder Gegenstand, jedes Material. Tipp oben ein Wort ein – oder blättere links durch die Kapitel.": "Qui trovi tutto su Klingenhort: ogni funzione, ogni oggetto, ogni materiale. Scrivi una parola in alto – o sfoglia i capitoli a sinistra.",
  "HÄUFIGE FRAGEN": "DOMANDE FREQUENTI",
  "KAPITEL": "CAPITOLI",
  "Nichts gefunden. Versuch ein anderes Wort – zum Beispiel „Holz“, „Schmiede“ oder „Drache“.": "Nessun risultato. Prova un'altra parola – per esempio «legno», «forgia» o «drago».",
  "1 Treffer": "1 risultato",
  "{n} Treffer": "{n} risultati",
  "… und {n} weitere. Gib ein Wort mehr ein.": "… e altri {n}. Aggiungi un'altra parola.",
  "{n} weitere Treffer zeigen": "Mostra altri {n} risultati",
  "Noch ein Buchstabe mehr …": "Ancora una lettera …",
  "ZULETZT GESUCHT": "RICERCHE RECENTI",
  "INHALT · {n} EINTRÄGE": "INDICE · {n} VOCI",
  "HANDBUCH": "MANUALE",
  "Suchen … z. B. Eisenholz": "Cerca … es. legno di ferro",
  "Im Handbuch suchen": "Cerca nel Manuale",
  "Suche leeren": "Cancella ricerca",
  "Handbuch": "Manuale",
  "Wo finde ich {mat}?": "Dove trovo {mat}?",
  "häufig": "comune",
  "selten": "raro",
  "sehr selten": "molto raro",
  "Bäume in den Endlosen Landen": "Alberi nelle Terre Infinite",
  "2–4 Holz je Baum – je weiter draußen, desto mehr (bis zu dreimal so viel). Kakteen und Knochenbäume geben manchmal 1, Sternenbäume 1–2.": "2–4 legno per albero – più ti allontani, più ne ottieni (fino al triplo). Cactus e alberi d'ossa a volte ne danno 1, gli alberi stellari 1–2.",
  "Felsen und Steine in den Endlosen Landen": "Rocce e sassi nelle Terre Infinite",
  "Große Felsen geben 3–5 Stein, kleine Steine 1–3 – tief draußen mehr. Auch Säulen, Kristalle und Korallen geben etwas.": "Le rocce grandi danno 3–5 pietra, i sassi piccoli 1–3 – nelle zone remote di più. Anche colonne, cristalli e coralli danno qualcosa.",
  "Büsche, Pilze und Kakteen": "Cespugli, funghi e cactus",
  "Büsche geben 1–2 Fasern, Pilze und Kakteen 2–3, Riesenpilze doppelt so viel. Kräuterbeete in den Landen manchmal 1.": "I cespugli danno 1–2 fibre, funghi e cactus 2–3, i funghi giganti il doppio. Le aiuole di erbe nelle Terre a volte 1.",
  "Büsche, Pilze, Bäume und Kräuterbeete": "Cespugli, funghi, alberi e aiuole di erbe",
  "Büsche (45 %), Pilze (50 %) und Bäume (12 %) lassen manchmal einen Samen fallen. Kräuterbeete in den Landen geben immer 1–2, Vogelnester manchmal einen.": "Cespugli (45%), funghi (50%) e alberi (12%) a volte lasciano cadere un seme. Le aiuole di erbe nelle Terre ne danno sempre 1–2, i nidi d'uccello a volte uno.",
  "Vogelnester in den Bäumen der Lande": "Nidi d'uccello sugli alberi delle Terre",
  "Etwa jeder 40. Baum trägt ein Nest. Beim ersten Treffer fällt es herunter: 2–4 Federn, weit draußen eine mehr. Büsche geben selten eine Feder.": "Circa un albero su 40 ha un nido. Al primo colpo cade giù: 2–4 piume, una in più nelle zone remote. I cespugli danno di rado una piuma.",
  "Bäume tiefer in den Landen": "Alberi nel profondo delle Terre",
  "Ab Stufe 13 (etwa {km} vom Weltentor) gibt jeder Baum manchmal 1–2 Eisenholz. Je tiefer, desto öfter – bis fast jeder zweite Baum.": "Dal grado 13 (a circa {km} dal Portale dei Mondi) ogni albero a volte dà 1–2 legno di ferro. Più vai in profondità, più spesso succede – fino a quasi un albero su due.",
  "Alte und dunkle Wälder: hier am meisten": "Foreste antiche e oscure: qui ce n'è di più",
  "In diesen Biomen gibt es viel mehr Eisenholz: {list}.": "In questi biomi c'è molto più legno di ferro: {list}.",
  "Weltenbäume: immer": "Alberi del Mondo: sempre",
  "Ein riesiger Weltenbaum gibt immer Eisenholz – gleich 3–6 Stück. Du findest sie als Wahrzeichen mancher Regionen und im {list}.": "Un enorme Albero del Mondo dà sempre legno di ferro – ben 3–6 pezzi. Li trovi come punto di riferimento di alcune regioni e in: {list}.",
  "Bäume weit draußen": "Alberi nelle zone remote",
  "Ab Stufe 55 (etwa {km} vom Weltentor) geben Bäume manchmal Sternholz – viel öfter in: {list}.": "Dal grado 55 (a circa {km} dal Portale dei Mondi) gli alberi a volte danno legno stellare – molto più spesso in: {list}.",
  "Sternen- und Glasbäume": "Alberi stellari e di vetro",
  "Geben immer 1–2 Sternholz. Sie wachsen in: {list}.": "Danno sempre 1–2 legno stellare. Crescono in: {list}.",
  "Felsen tiefer in den Landen": "Rocce nel profondo delle Terre",
  "Ab Stufe 16 (etwa {km} vom Weltentor) geben Felsen und Steine manchmal Marmor.": "Dal grado 16 (a circa {km} dal Portale dei Mondi) rocce e sassi a volte danno marmo.",
  "Helle Felsen": "Rocce chiare",
  "Hier gibt fast jeder Fels Marmor: {list}.": "Qui quasi ogni roccia dà marmo: {list}.",
  "Alte Säulen": "Colonne antiche",
  "Säulen geben 2–4 Marmor: {list}. Kristalle und Korallen manchmal einen.": "Le colonne danno 2–4 marmo: {list}. Cristalli e coralli a volte uno.",
  "Felsen weit draußen": "Rocce nelle zone remote",
  "Ab Stufe 36 (etwa {km} vom Weltentor) geben Felsen manchmal Obsidian.": "Dal grado 36 (a circa {km} dal Portale dei Mondi) le rocce a volte danno ossidiana.",
  "Dunkle Felsen": "Rocce scure",
  "Hier gibt etwa jeder zweite Fels Obsidian: {list}.": "Qui circa una roccia su due dà ossidiana: {list}.",
  "Obsidianfelsen": "Rocce di ossidiana",
  "Geben immer 1–3 Obsidian: {list}.": "Danno sempre 1–3 ossidiana: {list}.",
  "Knochenbäume und Riesenschädel": "Alberi d'ossa e teschi giganti",
  "Geben 2–3 Knochenstaub: {list}.": "Danno 2–3 polvere d'ossa: {list}.",
  "Leuchtende Kristalle": "Cristalli luminosi",
  "Kristalle in den Landen geben manchmal einen Seelenkristall: {list}.": "I cristalli nelle Terre a volte danno un cristallo d'anima: {list}.",
  "Schrott und große Felsen": "Rottami e rocce grandi",
  "Rostiger Schrott gibt 2–3 Eisenerz ({list}), große Felsen manchmal 1–2.": "I rottami arrugginiti danno 2–3 minerale di ferro ({list}), le rocce grandi a volte 1–2.",
  "Schrott weit draußen": "Rottami nelle zone remote",
  "Ab Stufe 14 gibt Schrott manchmal Mithrilerz: {list}.": "Dal grado 14 i rottami a volte danno minerale di mithril: {list}.",
  "Bäume": "Alberi",
  "Große Felsen": "Rocce grandi",
  "Steine": "Sassi",
  "Büsche": "Cespugli",
