  "immer {n} Stück": "sempre {n}",
  "{p} Chance – Elite-Gegner doppelt so oft und doppelt so viel": "{p} di probabilità – i nemici Élite il doppio delle volte e in quantità doppia",
  "Jeder Boss": "Ogni boss",
  "1–3 Drachenschuppen – in der Drachenwoche fallen sie auch bei normalen Gegnern.": "1–3 scaglie di drago – nella Settimana del Drago le lasciano cadere anche i nemici normali.",
  "Ab Akt 9 lässt jeder Gegner mit 3 % Chance einen Ätherkristall fallen, Elite dreimal so oft.": "Dall'Atto 9 ogni nemico ha il 3% di probabilità di lasciar cadere un cristallo d'etere, gli Élite il triplo.",
  "Akt {a}: {name}": "Atto {a}: {name}",
  "Erzadern in der Kampagne": "Vene di minerale nella campagna",
  "Hau mit Angriffen auf die Adern: 2–4 Stück. {list}": "Colpisci le vene con i tuoi attacchi: 2–4 pezzi. {list}",
  "Jede Erzader": "Ogni vena di minerale",
  "Gibt oft 1–2 Eisenerz extra, egal welches Erz sie trägt.": "Dà spesso 1–2 minerale di ferro extra, qualunque minerale contenga.",
  "Erzadern in den Endlosen Landen": "Vene di minerale nelle Terre Infinite",
  "Vor allem in: {list}.": "Soprattutto in: {list}.",
  "Truhen in der Kampagne": "Forzieri nella campagna",
