  "Die Gilde vergisst nie, wer ehrlich handelt. Und wer nicht.": "La Gilda non dimentica mai chi commercia onestamente. E chi no.",
  "Gold, das liegen bleibt, ist faules Gold. Lass es arbeiten!": "L'oro fermo è oro pigro. Fallo lavorare!",
  "Borin schmiedet, ich verkaufe – und du bringst uns beiden Arbeit.": "Borin forgia, io vendo – e tu porti lavoro a entrambi.",
