  "Stimme der Wildnis": "Voce della Selva",
  "Ei-Pflege hält 40 % länger, +30 % Sammelertrag, Acker 35 % schneller.": "Le cure alle uova durano il 40% in più, +30% di resa nella raccolta, campo il 35% più rapido.",
  "Jedes Ei, das du wärmst, jede Pflanze, die du erntest – die Wildnis merkt sich das.": "Ogni uovo che scaldi, ogni pianta che raccogli – la Selva se ne ricorda.",
  "Wer Bäume fällt, soll auch Samen säen. So halten wir es.": "Chi abbatte alberi deve anche seminare. Così facciamo noi.",
  "Ein Begleiter ist kein Werkzeug, Kind. Er ist Familie.": "Un compagno non è un attrezzo, piccolo. È famiglia.",
