  "DIESE WOCHE": "QUESTA SETTIMANA",
  "Jeder Auftrag gehört zu einer Fraktion: Abholen bringt Ruf und Ruf-Marken. Mit Ruf steigst du im Rang (Vorteile), mit Marken tauschst du beim Quartiermeister.": "Ogni missione appartiene a una fazione: ritirarla ti dà fama e gettoni di fama. Con la fama sali di rango (vantaggi), con i gettoni fai scambi dal Quartiermastro.",
