  "Vier Fraktionen. Ruf bringt Ränge mit kleinen, dauerhaften Vorteilen für alle deine Helden.": "Quattro fazioni. La fama porta ranghi con piccoli vantaggi permanenti per tutti i tuoi eroi.",
