  "Auftragstafel": "Bacheca delle missioni",
  "Tages- und Wochenaufträge, Ruf bei den Fraktionen und ihre Tauschangebote.": "Missioni giornaliere e settimanali, fama presso le fazioni e le loro offerte di scambio.",
  "Hier hängen deine Tages- und Wochenaufträge. Abholen bringt Gold, Material und Ruf bei einer der vier Fraktionen – und Ruf-Marken für ihre Tauschangebote.": "Qui sono appese le tue missioni giornaliere e settimanali. Ritirarle ti dà oro, materiali e fama presso una delle quattro fazioni – e gettoni di fama per le loro offerte di scambio.",
  "Zur Auftragstafel": "Alla Bacheca delle missioni",
  "Aufträge und Ruf": "Missioni e fama",
  "Tages- und Wochenaufträge, Fraktionen, Ruf-Marken": "Missioni giornaliere e settimanali, fazioni, gettoni di fama",
  "Jeden Tag drei neue Aufträge, jede Woche drei größere – mit Gold, Material und Ruf als Belohnung.": "Ogni giorno tre nuove missioni, ogni settimana tre più grandi – con oro, materiali e fama come ricompensa.",
  "Die Auftragstafel steht im Versteck zwischen Bibliothek und Lagerfeuer. Auf der Weltkarte findest du sie unter „Mehr“ → „Aufträge & Ruf“.": "La Bacheca delle missioni si trova nel Rifugio, tra la Biblioteca e il Falò. Sulla Mappa del mondo la trovi in «Altro» → «Missioni & fama».",
  "Tagesaufträge gibt es um Mitternacht neu, Wochenaufträge am Montag. Jeder Held hat seine eigenen.": "Le missioni giornaliere si rinnovano a mezzanotte, quelle settimanali il lunedì. Ogni eroe ha le sue.",
  "Die Ziele wachsen mit deinem Level. Es kommen nur Aufträge, die du gerade schaffen kannst – die Endlosen Lande zum Beispiel erst ab Level 5.": "Gli obiettivi crescono con il tuo livello. Arrivano solo missioni che puoi già completare – le Terre Infinite, per esempio, solo dal livello 5.",
  "Ist ein Auftrag erfüllt, bekommst du sofort eine Meldung. Abholen musst du ihn an der Tafel. Erfüllte Aufträge verfallen nicht – sie warten unter „Noch abzuholen“.": "Quando completi una missione ricevi subito un avviso. Il premio però lo ritiri alla bacheca. Le missioni compiute non scadono – ti aspettano in «Da ritirare».",
  "Belohnung: Gold, manchmal Glücksmünzen, Material (auch Holz, Eisenholz, Marmor …), Bauteile, ab und zu ein Mod oder ein Ei – dazu Ruf und Ruf-Marken. Wochenaufträge bringen etwa fünfmal so viel.": "Ricompensa: oro, a volte Monete della Fortuna, materiali (anche legno, legno di ferro, marmo …), componenti, ogni tanto un mod o un uovo – più fama e gettoni di fama. Le missioni settimanali danno circa cinque volte tanto.",
  "Alle Auftragsarten": "Tutti i tipi di missione",
  "Was eine Fraktion von dir will – Beispiele für dein Level.": "Cosa vuole da te ogni fazione – esempi per il tuo livello.",
  "Tag und Woche · Woche: {t}": "Giorno e settimana · Settimana: {t}",
  "Wochenauftrag": "Missione settimanale",
  "Tagesauftrag": "Missione giornaliera",
  "für dich gerade noch nicht dabei": "per ora non disponibile per te",
  "Die Zahlen passen zu deinem Level – höhere Level bekommen größere Ziele und mehr Belohnung.": "I numeri si adattano al tuo livello – ai livelli più alti, obiettivi più grandi e ricompense maggiori.",
  "Fraktionen, Ruf und Ränge": "Fazioni, fama e ranghi",
  "Vier Fraktionen – jeder Auftrag bringt Ruf bei einer von ihnen.": "Quattro fazioni – ogni missione ti dà fama presso una di esse.",
  "{n} Ränge · {s}": "{n} ranghi · {s}",
  "Ruf bekommst du für Aufträge der Fraktion. Bei den Kundschaftern zählen auch Elwas Aufträge in den Landen.": "Ottieni fama con le missioni della fazione. Per gli Esploratori contano anche le missioni di Elwa nelle Terre.",
  "Mit genug Ruf steigst du im Rang. Jeder Rang bringt einen kleinen, dauerhaften Vorteil – für alle deine Helden.": "Con abbastanza fama sali di rango. Ogni rango porta un piccolo vantaggio permanente – per tutti i tuoi eroi.",
  "Ruf geht nie verloren.": "La fama non si perde mai.",
  "Ruf-Marken und Quartiermeister": "Gettoni di fama e Quartiermastro",
  "Jede Fraktion zahlt mit eigenen Marken – getauscht wird an der Auftragstafel unter „TAUSCH“.": "Ogni fazione paga con i propri gettoni – gli scambi si fanno alla Bacheca delle missioni, in «BARATTO».",
  "Für jeden Auftrag gibt es Ruf-Marken seiner Fraktion: 2 bis 3 für einen Tagesauftrag, 8 bis 10 für einen Wochenauftrag.": "Ogni missione dà gettoni di fama della sua fazione: da 2 a 3 per una missione giornaliera, da 8 a 10 per una settimanale.",
  "Jede Woche hat jede Fraktion fünf andere Tauschangebote. Bezahlt wird mit Ruf-Marken und etwas Gold.": "Ogni settimana ogni fazione ha cinque offerte di scambio diverse. Si paga con gettoni di fama e un po' d'oro.",
  "Bessere Angebote gibt es erst ab einem bestimmten Rang: seltene Eier, Mods, seltene Rohstoffe, Leuchtfeuersteine, magische Vögel – und ganz oben ein Titel für deinen Helden.": "Le offerte migliori arrivano solo da un certo rango in su: uova rare, mod, materie prime rare, pietre del faro, uccelli magici – e in cima un titolo per il tuo eroe.",
  "Jedes Angebot gibt es nur ein paarmal pro Woche.": "Ogni offerta è disponibile solo poche volte a settimana.",
  "spricht für die Fraktion.": "parla a nome della fazione.",
