  "Weiter nach dem letzten Grund-Talent. Gesperrtes öffnet sich mit deinem Level, ganz unten wartet ein Schlussstein – voll ist der Baum erst bei Level {n}.": "Prosegue dopo l'ultimo talento Base. Ciò che è bloccato si apre con il tuo livello, in fondo ti aspetta una Chiave di volta – l'albero è completo solo al livello {n}.",
