  "Ab Level {lv} und Akt 5: zurück auf Level 1 und Akt 1. Ausrüstung, Materialien, Gold und Paragon bleiben. Dauerhaft +10 % Schaden und LP pro Wiedergeburt und eine goldene Aura. Bisher: {n}.": "Dal livello {lv} e dall'Atto 5: torni al livello 1 e all'Atto 1. Equipaggiamento, materiali, oro e Paragon restano. +10% permanente a danni e PS per ogni Rinascita e un'aura dorata. Finora: {n}.",
  "Level-Belohnungen gibt es je Held nur einmal – danach erst wieder ab Level {n}.": "Le ricompense di livello si ottengono una sola volta per eroe – dopo, di nuovo solo dal livello {n}.",
