  "Grenze erhöhen": "Alza la soglia",
  "Gilt von Gewöhnlich bis Episch überall dort, wo unten „Aufheben“ gewählt ist. Den Marktwert zeigt jeder Gegenstand.": "Vale da Comune a Epico ovunque sotto sia scelto «Raccogli». Ogni oggetto mostra il suo valore di mercato.",
  "Deine Ausrüstung: {list}": "Il tuo equipaggiamento: {list}",
  "NACH SELTENHEIT": "PER RARITÀ",
  "Was besser ist als deine Ausrüstung, hebst du immer auf.": "Ciò che è migliore del tuo equipaggiamento lo raccogli sempre.",
  "Legendär, Set und Mythisch hebst du immer auf – ebenso alles mit Mods, Sockelsteinen oder Aufwertung.": "Leggendari, Set e Mitici li raccogli sempre, così come tutto ciò che ha mod, gemme incastonate o potenziamenti.",
  "Verkaufen bringt sofort den Händlerpreis. Wegwerfen: Der Gegenstand verschwindet, sobald du darüber läufst – kein Gold, kein Platz im Beutel.": "Vendere ti dà subito il prezzo del mercante. Butta: l'oggetto sparisce appena ci passi sopra – niente oro, niente spazio nella borsa.",
